  // Older high-scale assets stay as unique card art, while every refreshed card above points to a new dedicated 3:2 image.
  V.forEach(tier=>{
    if(!Number.isInteger(tier.legacyHighIndex)) return;
    tier.cards.forEach((card,cardIndex)=>{
      if(!card.image.startsWith('images/refresh/')) card.image=`images/cards/t${tier.legacyHighIndex+12}-c${cardIndex+1}.webp`;
    });
  });
